import{_ as e,c as o,o as a,ag as r}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Matrix Bots","description":"","frontmatter":{"title":"Matrix Bots"},"headers":[],"relativePath":"matrix/matrix-bots.md","filePath":"matrix/matrix-bots.md","lastUpdated":null}'),i={name:"matrix/matrix-bots.md"};function n(s,t,l,c,u,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="matrix-bots" tabindex="-1">Matrix Bots <a class="header-anchor" href="#matrix-bots" aria-label="Permalink to &quot;Matrix Bots&quot;">​</a></h1><p>Return to <a href="/server-guides/mantrix-with-ansible.html">Server Guides</a></p><h2 id="gpt-bot" tabindex="-1">GPT Bot <a class="header-anchor" href="#gpt-bot" aria-label="Permalink to &quot;GPT Bot&quot;">​</a></h2><p>For setting up a GPT-powered bot, follow the instructions provided in the official documentation:</p><ul><li><a href="https://github.com/spantaleev/matrix-docker-ansible-deploy/blob/64db27c7faf3032341c665f8abf7aa66c7aa7aca/docs/configuring-playbook-bot-chatgpt.md?plain=1#L45" target="_blank" rel="noreferrer">Matrix-Docker-Ansible-Deploy GPT Bot Guide</a></li></ul><h3 id="required-setup" tabindex="-1">Required Setup <a class="header-anchor" href="#required-setup" aria-label="Permalink to &quot;Required Setup&quot;">​</a></h3><p>Before proceeding, ensure you have the following:</p><ul><li><strong>OpenAI GPT Models</strong>: Detailed information can be found <a href="https://platform.openai.com/docs/models/gpt-4-and-gpt-4-turbo" target="_blank" rel="noreferrer">here</a>.</li><li><strong>GPT API Key</strong>: Generate your API key <a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">here</a>.</li><li><strong>Pricing Information</strong>: Understand GPT pricing <a href="https://openai.com/pricing" target="_blank" rel="noreferrer">here</a>.</li></ul><h3 id="setting-up-a-bot-account-with-sso" tabindex="-1">Setting Up a Bot Account with SSO <a class="header-anchor" href="#setting-up-a-bot-account-with-sso" aria-label="Permalink to &quot;Setting Up a Bot Account with SSO&quot;">​</a></h3><p>Follow these steps to create a bot account using SSO:</p><ol><li><strong>Create an account</strong>: Register a bot account using your SSO provider.</li><li>Open a <strong>private browser window</strong> and log in to Matrix using the SSO.</li><li>Set up <strong>recovery keys</strong> for the account.</li><li>Obtain the <strong>access token</strong> for the bot account: <ul><li>Navigate to <strong>All Settings</strong> in the Matrix client.</li><li>Go to <strong>Help &amp; About</strong>.</li><li>Select <strong>Access Token</strong> and copy it.</li></ul></li><li><strong>DO NOT LOG OUT</strong>: Keep the session active.</li><li>Close the browser to maintain the session state.</li><li>Use the obtained access token to configure the bot.</li></ol><p><strong>Important Note:</strong> For SSO accounts, removing the local password option is required to allow recovery keys to be set up. Ensure this is configured correctly before proceeding.</p><h3 id="setting-up-an-account-with-an-access-token" tabindex="-1">Setting Up an Account with an Access Token <a class="header-anchor" href="#setting-up-an-account-with-an-access-token" aria-label="Permalink to &quot;Setting Up an Account with an Access Token&quot;">​</a></h3><p>Refer to the discussion and solutions provided in the <a href="https://github.com/spantaleev/matrix-docker-ansible-deploy/issues/2556" target="_blank" rel="noreferrer">GitHub Issue #2556</a> for detailed guidance on using an access token for account setup.</p>',14)])])}const g=e(i,[["render",n]]);export{d as __pageData,g as default};
